use crate::{crypto, der, rsa};
use num_bigint::BigUint;
use rand::{thread_rng, RngCore};
use sha2::{Digest, Sha256};
use std::{io, str};

pub const MAGIC: &[u8]=b"GOAT\x01"; pub const VERSION:u64=1; pub const STAGE_BASE:u64=0x180100000; pub const STAGE_SIZE:u64=0xe8000; pub const SRAM_END:u64=STAGE_BASE+STAGE_SIZE; pub const DEFAULT_LOAD_BASE:u64=0x180180000;
fn bad(s:impl Into<String>)->io::Error{io::Error::new(io::ErrorKind::InvalidData,s.into())}
#[derive(Debug,Clone)] pub struct Parsed { pub payload_sha:Vec<u8>,pub payload_len:usize,pub load_base:u64,pub entry_off:u64,pub iv:Vec<u8>,pub cipher:Vec<u8>,pub keywrap:Option<Vec<u8>>,pub serial:u64,pub issuer:String,pub subject:String,pub not_before:u64,pub not_after:u64,pub modulus:Vec<u8>,pub exponent:Vec<u8>,pub cert_sig:Vec<u8>,pub cert_tbs:Vec<u8>,pub signed:Vec<u8>,pub signature:Vec<u8> }
pub fn parse(b:&[u8])->io::Result<Parsed>{let top=der::parse(b)?;if top.total!=b.len()||top.tag!=0x30{return Err(bad("container is not an exact SEQUENCE"))}let t=der::children(&top)?;if t.len()!=4||t[0].content!=MAGIC||der::read_uint(&t[1])?!=VERSION{return Err(bad("invalid GOAT header"))}let body=der::children(&t[2])?;if body.len()!=3{return Err(bad("invalid container body"))}let pf=der::children(&body[0])?;let ef=der::children(&body[1])?;let cf=der::children(&body[2])?;if pf.len()!=4||ef.len()<2||ef.len()>3||cf.len()!=2{return Err(bad("invalid container fields"))}let tf=der::children(&cf[0])?;if tf.len()!=6{return Err(bad("invalid certificate TBS"))}let pk=der::children(&tf[5])?;if pk.len()!=2{return Err(bad("invalid public key"))}let signed=top.content[t[2].start..t[2].start+t[2].total].to_vec();let cert_tbs=body[2].content[cf[0].start..cf[0].start+cf[0].total].to_vec();let issuer=str::from_utf8(tf[1].content).map_err(|_|bad("invalid issuer"))?.to_owned();let subject=str::from_utf8(tf[2].content).map_err(|_|bad("invalid subject"))?.to_owned();let keywrap=if ef.len()==3{let x=der::children(&ef[2])?;if x.len()!=2{return Err(bad("invalid key wrap"))}Some(x[1].content.to_vec())}else{None};Ok(Parsed{payload_sha:pf[0].content.to_vec(),payload_len:der::read_uint(&pf[1])? as usize,load_base:der::read_uint(&pf[2])?,entry_off:der::read_uint(&pf[3])?,iv:ef[0].content.to_vec(),cipher:ef[1].content.to_vec(),keywrap,serial:der::read_uint(&tf[0])?,issuer,subject,not_before:der::read_uint(&tf[3])?,not_after:der::read_uint(&tf[4])?,modulus:pk[0].content.to_vec(),exponent:pk[1].content.to_vec(),cert_sig:cf[1].content.to_vec(),cert_tbs,signed,signature:t[3].content.to_vec()})}
impl Parsed { pub fn cert_ok(&self)->bool{rsa::verify(&BigUint::from_bytes_be(&self.modulus),&BigUint::from_bytes_be(&self.exponent),&self.cert_sig,&self.cert_tbs)} pub fn verify(&self)->bool{self.cert_ok()&&rsa::verify(&BigUint::from_bytes_be(&self.modulus),&BigUint::from_bytes_be(&self.exponent),&self.signature,&self.signed)} pub fn decrypt(&self,key:&[u8])->io::Result<Vec<u8>>{let p=crypto::decrypt_cbc(key,&self.iv,&self.cipher)?;if p.len()!=self.payload_len||Sha256::digest(&p).as_slice()!=self.payload_sha{return Err(bad("payload length or digest mismatch"))}Ok(p)} pub fn unwrap(&self,d:&BigUint)->io::Result<Vec<u8>>{rsa::unwrap(&BigUint::from_bytes_be(&self.modulus),d,self.keywrap.as_ref().ok_or_else(||bad("container has no wrapped key"))?)} }
pub fn seal(payload:&[u8],key:&[u8],identity:&serde_json::Value,base:u64,entry:u64,wrap:bool)->io::Result<Vec<u8>>{if payload.is_empty(){return Err(bad("refusing to seal an empty payload"))}if key.len()!=32{return Err(bad("AES key must be 32 bytes"))}if base<STAGE_BASE||base+payload.len() as u64>SRAM_END||entry>=payload.len() as u64{return Err(bad("payload placement is outside the Goat SRAM window"))}let num=|k:&str|->io::Result<BigUint>{let s=identity[k].as_str().ok_or_else(||bad("key field is not a string"))?;BigUint::parse_bytes(s.trim_start_matches("0x").as_bytes(),16).ok_or_else(||bad("invalid key integer"))};let n=num("n")?;let e=num("e")?;let d=num("d")?;let mut iv=[0u8;16];thread_rng().fill_bytes(&mut iv);let cipher=crypto::encrypt_cbc(key,&iv,payload)?;let pf=der::seq(&[der::octets(&Sha256::digest(payload)),der::uint(payload.len() as u64),der::uint(base),der::uint(entry)]);let mut enc=vec![der::octets(&iv),der::octets(&cipher)];if wrap{enc.push(der::seq(&[der::uint(1),der::octets(&rsa::wrap(&n,&e,key)?)]))}let cert=rsa::certificate(&n,&e,&d,identity["serial"].as_u64().unwrap_or(1),identity["issuer"].as_str().unwrap_or("goat"),identity["subject"].as_str().unwrap_or("goat"),identity["not_before"].as_u64().unwrap_or(0),identity["not_after"].as_u64().unwrap_or(4102444800))?;let body=der::seq(&[pf,der::seq(&enc),cert]);let sig=rsa::sign_private(&n,&d,&body)?;Ok(der::seq(&[der::octets(MAGIC),der::uint(VERSION),body,der::octets(&sig)]))}
pub fn inspect(b:&[u8])->io::Result<String>{let c=parse(b)?;Ok(format!("goat container: {} bytes\n  version       : 1\n  payload sha256: {}\n  payload length: {} (0x{:x})\n  load base     : 0x{:x}\n  entry offset  : 0x{:x} -> entry 0x{:x}\n  iv            : {}\n  ciphertext    : {} bytes\n  certificate   :\n    subject     : {}\n    issuer      : {}\n    serial      : 0x{:x}\n    not before  : {}\n    not after   : {}\n    key         : {} bit\n  keywrap       : {}\n  signature     : {} bytes\n",b.len(),hex(&c.payload_sha),c.payload_len,c.payload_len,c.load_base,c.entry_off,c.load_base+c.entry_off,hex(&c.iv),c.cipher.len(),c.subject,c.issuer,c.serial,c.not_before,c.not_after,c.modulus.len()*8,if c.keywrap.is_some(){"present"}else{"none"},c.signature.len()))}
fn hex(v:&[u8])->String{v.iter().map(|x|format!("{x:02x}")).collect()}
